const env = import.meta.env; // from vite
;
export const defaultMockResponse = { ok: true, data: 'default-mock-response' };
export default function squizInfo(overload = {}) {
    return {
        ...overload,
        ctx: {
            ...overload.ctx || {}
        },
        env,
        fns: {
            resolveUri: async (uri) => Promise.resolve(overload?.mock?.resolveUri?.(uri) ?? defaultMockResponse),
            resolveMatrixAssetById: async (assetid, attributes) => Promise.resolve(overload?.mock?.resolveMatrixAssetById?.(assetid, attributes) ?? defaultMockResponse),
            resolveMatrixAssetByUrl: async (url, attributes) => Promise.resolve(overload?.mock?.resolveMatrixAssetByUrl?.(url, attributes) ?? defaultMockResponse),
        }
    };
}
